ePath":"src/db.js","value":{"icon":"flame","title":"برامج اللياقة والقوة","title_en":"Fitness and strength programs","text":"برامج تساعد الموظفين على النشاط البدني وكسر الروتين.","text_en":"Programs that encourage physical activity and help teams break their routine."}}},{"source_table":"source_code_companies","source_key":"3","data":{"sourcePath":"src/db.js","value":{"icon":"calendar","title":"جدولة مخصصة للجهات","title_en":"Scheduling tailored to each organization","text":"يمكن تخصيص الأوقات والبرنامج وفق عدد المشاركين وأهداف الجهة.","text_en":"Times and programs can be tailored to the group size and organization’s goals."}}},{"source_table":"site_snapshot","source_key":"work/site-snapshot.json","data":{"settings":{"club_name":"فايت كلوب","club_name_en":"Fight Club","tagline":"نادي الفنون القتالية","tagline_en":"Combat Sports Club","meta_description":"فايت كلوب — نادي ملاكمة ومواي تاي وجوجيتسو وMMA. اشترك الآن وتابع اشتراكك وجدول الحصص أونلاين.","meta_description_en":"Fight Club — boxing, Muay Thai, Brazilian Jiu-Jitsu and MMA. Join today and follow your membership and class schedule online.","phone":"0530335050","whatsapp":"0530335050","email":"fightclubssaudi@gmail.com","address":"حي المروج، الرياض، المملكة العربية السعودية","address_en":"Al Muruj, Riyadh, Saudi Arabia","hours":"","hours_en":"","map_url":"","instagram":"https://www.instagram.com/fightclubksa/","x":"","snapchat":"","tiktok":"","currency":"ر.س","currency_en":"SAR","country_code":"966","marquee":"ملاكمة,مواي تاي,تايكوندو,جوجيتسو,مصارعة","marquee_en":"BOXING,MUAY THAI,TAEKWONDO,JIU-JITSU,WRESTLING","week_start":"6","expiring_days":"3","footer_text":"جميع الحقوق محفوظة","footer_text_en":"All rights reserved","msg_expired":"مرحباً {name}، انتهى اشتراكك في {club} بتاريخ {date}. جدّد اشتراكك للاستمرار في التدريب.","msg_expired_en":"Hello {name}, your {club} membership expired on {date}. Renew to keep training.","msg_expiring":"مرحباً {name}، ينتهي اشتراكك في {club} بتاريخ {date}. جدّد قبل الانتهاء حتى لا ينقطع تدريبك.","msg_expiring_en":"Hello {name}, your {club} membership expires on {date}. Renew before then to keep training.","msg_renewed":"تم تجديد اشتراكك في {club} حتى {date}. نتمنى لك تدريباً موفقاً.","msg_renewed_en":"Your {club} membership has been renewed through {date}. Enjoy your training."},"sections":[{"id":1,"type":"hero","anchor":"home","nav_label":"","title":"قاتل بقوة، وتدرّب بانضباط","subtitle":"ملاكمة · مواي تاي · تايكوندو · جوجيتسو · مصارعة — برامج للصغار والكبار.","body":"","items":[{"btn":"اشترك الآن","link":"#pricing","btn_en":"Join now"},{"btn":"جدول الحصص","link":"#schedule","btn_en":"Class schedule"}],"position":0,"visible":1,"nav_label_en":"","title_en":"Train hard. Fight with discipline.","subtitle_en":"Boxing · Muay Thai · Taekwondo · Jiu-Jitsu · Wrestling — classes for children and adults.","body_en":""},{"id":2,"type":"text","anchor":"about","nav_label":"عن النادي","title":"من نحن","subtitle":"تأسس فايت كلوب في الرياض عام 2016، ويقدّم تدريباً متخصصاً في الفنون القتالية واللياقة البدنية للأطفال والكبار، من المبتدئين إلى المتقدمين.","body":"تأسس فايت كلوب في الرياض عام 2016 ليقدم تدريباً متخصصاً في الفنون القتالية واللياقة البدنية. نهيئ حصصاً تناسب الأطفال والكبار، من المبتدئين إلى المتقدمين، في بيئة منظمة تشجع على الانضباط والاحترام والتطور.\n\nرسالتنا أن نمنح كل متدرب بداية صحيحة وفرصة حقيقية للتطور وتحقيق أهدافه، سواء كانت تحسين اللياقة، تعلم مهارة جديدة أو الاستعداد للمنافسة.","items":[{"value":"5","label":"رياضات قتالية","label_en":"combat sports"},{"value":"3","label":"فئات تدريب","label_en":"training groups"},{"value":"9","label":"خيارات اشتراك","label_en":"membership options"}],"position":1,"visible":1,"nav_label_en":"About us","title_en":"Who we are","subtitle_en":"Founded in Riyadh in 2016, Fight Club offers focused martial arts and fitness training for children and adults, from beginners to advanced athletes.","body_en":"Fight Club was founded in Riyadh in 2016 to provide focused martial arts and fitness training. Our classes are designed for children and adults, from beginners to advanced athletes, in an organized environment built on discipline, respect and progress.\n\nOur mission is to give every member a strong start and a real opportunity to reach their goals, whether that means improving fitness, learning a new skill or preparing to compete."},{"id":3,"type":"cards","anchor":"programs","nav_label":"البرامج","title":"اختر رياضتك","subtitle":"من الرياضات القتالية إلى اللياقة والقوة — برامج تناسب أهدافك ومستواك","body":"","items":[{"icon":"glove","title":"الملاكمة","title_en":"Boxing","text":"حصص ملاكمة منظمة وآمنة تطور اللياقة والتحمل والتركيز والثقة، وتناسب مستويات مختلفة.","text_en":"Structured boxing classes build fitness, endurance, focus and confidence for different levels."},{"icon":"flame","title":"مواي تاي","title_en":"Muay Thai","text":"تدريب على الركلات واللكمات والركب والمرفقين، مع التركيز على القوة والتوازن والانضباط.","text_en":"Train punches, kicks, knees and elbows while developing strength, balance and discipline."},{"icon":"belt","title":"تايكوندو","title_en":"Taekwondo","text":"طوّر سرعتك ومرونتك وتقنيات الركل.","text_en":"Develop speed, flexibility and kicking technique."},{"icon":"trophy","title":"جوجيتسو","title_en":"Jiu-Jitsu","text":"طوّر التحكم والهدوء وحل المشكلات تحت الضغط، مع حصص مناسبة للمبتدئين.","text_en":"Build control, composure and problem-solving under pressure, with classes suitable for beginners."},{"icon":"shield","title":"مصارعة","title_en":"Wrestling","text":"قوّة وتوازن وإسقاطات تحت إشراف المدرب.","text_en":"Build strength, balance and takedowns with a coach."},{"icon":"shield","title":"الفنون القتالية المختلطة MMA","title_en":"Mixed Martial Arts (MMA)","text":"تدريب منظم يجمع أساليب قتالية متعددة ويطوّر اللياقة والتحمل.","text_en":"Structured training that combines multiple martial arts and builds fitness and endurance."},{"icon":"flame","title":"اللياقة والقوة","title_en":"Strength & Fitness","text":"مساحة متكاملة لتطوير القوة واللياقة بإشراف المدربين.","text_en":"A dedicated space to improve strength and fitness with coach guidance."}],"position":2,"visible":1,"nav_label_en":"Programs","title_en":"Choose your discipline","subtitle_en":"From combat sports to strength and fitness — programs for your goals and level","body_en":""},{"id":4,"type":"pricing","anchor":"pricing","nav_label":"الأسعار","title":"باقات الاشتراك","subtitle":"اختر المدة المناسبة وابدأ اليوم","body":"","items":[],"position":3,"visible":1,"nav_label_en":"Membership","title_en":"Membership plans","subtitle_en":"Choose a plan and get started today","body_en":""},{"id":5,"type":"offers","anchor":"offers","nav_label":"العروض","title":"العروض الحالية","subtitle":"فرص محدودة — لا تفوّتها","body":"","items":[],"position":4,"visible":1,"nav_label_en":"Offers","title_en":"Current offers","subtitle_en":"Limited-time offers — do not miss out","body_en":""},{"id":6,"type":"schedule","anchor":"schedule","nav_label":"الجدول","title":"جدول الحصص","subtitle":"حصص للصغار والكبار من السبت إلى الخميس — اختر يوماً لعرض المواعيد","body":"","items":[],"position":5,"visible":1,"nav_label_en":"Schedule","title_en":"Class schedule","subtitle_en":"Classes for children and adults, Saturday through Thursday. Choose a day to see the times.","body_en":""},{"id":9,"type":"cards","anchor":"coaches","nav_label":"المدربون","title":"نخبة المدربين","subtitle":"خبرات في الملاكمة، المواي تاي، الجوجيتسو، التايكوندو والفنون القتالية المختلطة.","body":"","items":[{"title":"فراس سعدة","title_en":"Firas Saadah","text":"مدرب المنتخب السعودي للمواي تاي. يمتلك خبرة عالية في تأسيس اللاعبين وتطويرهم لمختلف المستويات.","text_en":"Muay Thai coach for the Saudi national team, with extensive experience developing athletes at different levels.","image":"/assets/trainers/firas-saadah.jpg"},{"title":"جوزيه ماريا تومي","title_en":"Jose Maria Tomy","text":"مدرب MMA وحاصل على الحزام الأسود في الجوجيتسو، ومقاتل سابق في UFC. شارك ضمن الطاقم التدريبي لإسلام ماخاشيف.","text_en":"MMA coach, Brazilian Jiu-Jitsu black belt and former UFC fighter. Has worked on the coaching team of Islam Makhachev.","image":"/assets/trainers/jose-maria-tomy.jpg"},{"title":"عبدالله جاويش","title_en":"Abdullah Jawish","text":"مدرب جوجيتسو وحاصل على الحزام الأسود. بطل عالم 18 مرة، ويتميز بخبرته في تدريب الأطفال والكبار.","text_en":"Jiu-Jitsu coach and black belt, described in the club brochure as an 18-time world champion, with experience coaching children and adults.","image":"/assets/trainers/abdullah-jawish.jpg"},{"title":"سفيان الزريدي","title_en":"Soufiane Zridy","text":"مدرب مواي تاي وبطل عالم سبع مرات، متخصص في تأسيس اللاعبين والتطوير الفني والبدني.","text_en":"Muay Thai coach and seven-time world champion, specializing in athlete development and technical and physical training.","image":"/assets/trainers/soufiane-zridy.jpg"},{"title":"رؤى سليم","title_en":"Roua Salim","text":"مدربة سابقة للمنتخب الأردني وحكم دولي في التايكوندو، ولديها خبرة في تأسيس الأطفال وتطويرهم.","text_en":"Former Jordanian national team coach and international Taekwondo referee, with experience developing young athletes.","image":"/assets/trainers/roua-salim.jpg"},{"title":"عادل بيك","title_en":"Adel Bek","text":"مدرب ملاكمة أولمبي من أوزبكستان، يقدم أسلوب المدرسة السوفيتية للمبتدئين والمحترفين.","text_en":"Olympic boxing coach from Uzbekistan, bringing the Soviet-school approach to beginner and professional athletes.","image":"/assets/trainers/adel-bek.jpg"},{"title":"عبدالكريم الزريدي","title_en":"Abdelkarim Zridy","text":"مدرب ملاكمة في الرياض. تشمل إنجازاته ألقاباً في المغرب والسعودية، وبطولة أفضل لاعب 2017، ومركز الوصافة في دورة الألعاب السعودية 2023 بوزني 60 و63 كجم.","text_en":"Boxing coach in Riyadh. His listed achievements include Moroccan and Saudi titles, the 2017 Best Player Cup and second place at the 2023 Saudi Games in the 60 kg and 63 kg divisions.","image":"/assets/trainers/abdelkarim-zridy.jpg","phone":"0551796505","email":"zroud63.5@gmail.com"}],"position":6,"visible":1,"nav_lab